package com.hms.sbl.v2.services.processor.impl.smpp;

import com.hms.sbl.v2.configuration.SmsMoHttpConfig;
import com.hms.sbl.v2.services.MessageSenderService;
import hms.commons.SnmpLogUtil;
import hsenidmobile.smpp.api.SmppMessage;
import org.apache.hc.client5.http.classic.methods.HttpPost;
import org.apache.hc.core5.http.ContentType;
import org.apache.hc.core5.http.io.entity.ByteArrayEntity;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectOutputStream;
import java.util.Map;
import java.util.Set;

@Component
public class SdpMessageSender {
    private static final Logger logger = LoggerFactory.getLogger(SdpMessageSender.class);

    @Autowired
    private MessageSenderService messageSenderService;

    @Autowired
    private SmsMoHttpConfig smsMoHttpConfig;

    private static final String CORE_ROUTE_FAIL_KEY = "CORE_ROUTE_FAIL";

    public void send(SmppMessage message, String url) {
        HttpPost httpPost = createHttpMethod(message, url);
        try {
            setSerializeData(message, httpPost);
            messageSenderService.executeMethod(message.getCorrelationId(), url, httpPost);
            SnmpLogUtil.clearTrap(CORE_ROUTE_FAIL_KEY, "Message routed to core successfully");
        } catch (Exception e) {
            SnmpLogUtil.trap(CORE_ROUTE_FAIL_KEY, "SBL:Sending message to Core URL " + url + " failed.");
            logger.error("An error occurred while preparing and sending message to SDP correlationId [{}]", message.getCorrelationId(), e);
            throw new RuntimeException(e);
        }
    }

    private HttpPost createHttpMethod(SmppMessage smsMessage, String url) {
        Map<String, Object> requestHeaders = smsMessage.getExtraHeaderDetails();
        HttpPost httpPost = new HttpPost(url);
        setConfiguredHttpHeaderParameters(httpPost);
        if (requestHeaders == null) {
            logger.warn("RequestHeaders are not provided with given message.]");
        } else {
            if (smsMoHttpConfig.getRouting() != null) {
                for (String headerName : smsMoHttpConfig.getRouting()) {
                    String headerValue = (String) requestHeaders.get(headerName);
                    if (headerValue != null && !headerValue.trim().isEmpty()) {
                        if (logger.isDebugEnabled()) {
                            logger.debug("Setting routing header [" + headerName + "] to http request");
                        }
                        httpPost.setHeader(headerName, headerValue);
                    }
                }
            } else {
                if (logger.isDebugEnabled()) {
                    logger.debug("ROUTING_HEADER_PARAMS are not provided in PropertyHolder");
                }
            }

        }
        return httpPost;
    }

    private void setConfiguredHttpHeaderParameters(HttpPost httpPost) {
        if (smsMoHttpConfig.getTransport() != null && !smsMoHttpConfig.getTransport().isEmpty()) {
            Set<String> httpHeaders = smsMoHttpConfig.getTransport().keySet();
            for (String header : httpHeaders) {
                String headerValue = smsMoHttpConfig.getTransport().get(header);
                if (headerValue != null && !headerValue.trim().isEmpty()) {
                    if (logger.isDebugEnabled()) {
                        logger.debug("Setting http header parameter [" + header + "] [" + headerValue + "]");
                    }
                    httpPost.setHeader(header, headerValue);
                }
            }
        }
    }

    private void setSerializeData(SmppMessage smsMessage, HttpPost httpPost) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);
        objectOutputStream.writeObject(smsMessage);

        ByteArrayEntity entity = new ByteArrayEntity(byteArrayOutputStream.toByteArray(), ContentType.APPLICATION_OCTET_STREAM);
        httpPost.setEntity(entity);

        objectOutputStream.close();
        byteArrayOutputStream.close();
    }

}

