package com.hms.sbl.v2.sms;

import com.hms.sbl.v2.services.processor.impl.smpp.SdpMessageSender;
import hsenidmobile.smpp.api.DeliverSmNotify;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.apache.log4j.NDC;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * @author sandarenu $LastChangedDate: 2009-03-02 17:31:42 +0800 (Mon, 02 Mar 2009) $
 *         $LastChangedBy: sandarenu $ $LastChangedRevision: 43884 $
 */

@Component
public class DeliverSmNotifyRouter {

    private final static Logger logger = LoggerFactory.getLogger(DeliverSmNotifyRouter.class);

	@Autowired
	private SdpMessageSender sdpMessageSender;

	@Value("${sms.delivery-report.routing-endpoint}")
	private String deliveryReportRoutingEndpoint;

	public void route(DeliverSmNotify notifyMessage) {
		NDC.push("CorrelationId[" + notifyMessage.getCorrelationId() + "]");
		try {
			if (logger.isDebugEnabled()) {
				logger.debug("Sending DeliverSmNotify to Core-------------START");
			}

			if (notifyMessage == null) {
				return;
			}

			logger.info("[DELIVER_SM_NOTIFY] Sending notify message to Core [" + notifyMessage + "]");
			sdpMessageSender.send(notifyMessage, deliveryReportRoutingEndpoint + "/"
					+ notifyMessage.getNcsId());

			if (logger.isDebugEnabled()) {
				logger.debug("Sending DeliverSmNotify to Core-------------END");
			}
		} finally {
			NDC.pop();
		}

	}

	public void route(List<DeliverSmNotify> notifyMessages) {
		if (logger.isDebugEnabled()) {
			logger.debug("Sending DeliverSmNotify List to Core-------------START");
		}

		if (notifyMessages == null) {
			return;
		}

		for (DeliverSmNotify deliverSmNotify : notifyMessages) {
			route(deliverSmNotify);
		}

		if (logger.isDebugEnabled()) {
			logger.debug("Sending DeliverSmNotify List to Core-------------END");
		}
	}

}

