private void processTimedOutMessages(List<SubmitResponseData> messages) {
    if (logger.isDebugEnabled()) {
        logger.debug("Timeouting [" + messages.size() + "] DeliverNotify messages.");
    }
    for (SubmitResponseData smsMessage : messages) {
        if (blacklistService.isBlackListed(smsMessage.getCorrelationId())) {
            logger.info("Message is blacklisted. Ignoring the timeout message [ correlationId: " + smsMessage.getCorrelationId() + ", destinationAddress: " + smsMessage.getDestinationAddress() + "]");
        } else {
            try {
                logger.info("Processing Timeout message [message: " + smsMessage + "]");
                DeliverSmNotify deliverNotify = encodeTimeOutedDeliverSMNotify(smsMessage);

                if (deliverNotify == null) {
                    logger.warn("Application is unable to load dr [ correlationId: " + smsMessage.getCorrelationId()
                            + "messageId: " + smsMessage.getMessageId() + ", destinationAddress: " + smsMessage.getDestinationAddress() + "]");
                    continue;
                }

                routeTimedOutNotifies(deliverNotify);

                logger.info("Clearing all processed timeout delivery report with correlationId: " + smsMessage.getCorrelationId() + ", destinationAddress: " + smsMessage.getDestinationAddress());
                deliveryReportDao.deleteByCorrelationId(smsMessage.getCorrelationId());

                logger.info("Clearing all timeout messages with correlationId: " + smsMessage.getCorrelationId() + ", destinationAddress: " + smsMessage.getDestinationAddress());
                deliverNotifyDAO.deleteByCorrelationId(smsMessage.getCorrelationId());

                logger.info(new StringBuilder(200).append("[DELIVER_SM_NOTIFI] Timeouting DeliverNotify message.").append(
                        " Correlation id [").append(deliverNotify.getCorrelationId()).append("]").toString());
            } catch (Throwable e) {
                logger.error("Error while processing timeout DeliverNotify message.", e);
            }

        }
    }
}

private void routeTimedOutNotifies(DeliverSmNotify deliverNotify) {
    if (deliverNotify == null) {
        return;
    }

