package com.hms.sbl.v2.services.smpp;

import com.hms.sbl.v2.services.processor.impl.smpp.SdpMessageSender;
import hsenidmobile.smpp.api.LargeSM;
import hsenidmobile.smpp.api.ShortMessageFragment;
import hsenidmobile.smpp.api.SmppMessage;
import hsenidmobile.smpp.api.SubmitMultiLargeSm;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

@Component
public class SmsMtResRouter {
    private static final Logger logger = LoggerFactory.getLogger(SmsMtResRouter.class);

    @Autowired
    private SdpMessageSender sdpMessageSender;

    @Value("${sms.submit-res.routing-url-name}")
    private String submitResponseRoutingUrlName;// MT-RESP-REPLY-URL

    @Value("${sbl.sms-mt-res-default-url}")
    private String smsMtResDefaultUrl;

    @Value("${sms.submit-res.use-default-routing}")
    private Boolean useDefaultRespRouting;

    public void route(SmppMessage sentMessage) {
        if (logger.isDebugEnabled()) {
            logger.debug("Sending SubmitSmResp to Core.........START");
        }

        //Remove the responses received and message fragments sent when sending the response back to core.
        //This is done to solve an issue related to Terracotta when sending large http message to core side,
        //it is not being delivered properly.
        if(sentMessage instanceof LargeSM){
            if (logger.isDebugEnabled()) {
                logger.debug("Message received to sent to core is [LargeSM], removed individual responses and message fragments given to send.");
            }
            LargeSM largeSM = (LargeSM)sentMessage;
            List<ShortMessageFragment> dummyList = new ArrayList<ShortMessageFragment>(1);
            dummyList.add(new ShortMessageFragment());
            largeSM.setMessageFragments(dummyList);
            largeSM.setReceivedResponses(null);
        } else if(sentMessage instanceof SubmitMultiLargeSm){
            if (logger.isDebugEnabled()) {
                logger.debug("Message received to sent to core is [SubmitMultiLargeSm],removed message fragments given to send.");
            }
            SubmitMultiLargeSm largeSM = (SubmitMultiLargeSm)sentMessage;
            List<ShortMessageFragment> dummyList = new ArrayList<ShortMessageFragment>(1);
            dummyList.add(new ShortMessageFragment());
            largeSM.setMessageFragments(dummyList);
            //For SubmitMultiLargeSm we don't remove individual responses since those are used in the
            //core to determine failed Msisdns if any.
        } else {
            if (logger.isDebugEnabled()) {
                String messageType = sentMessage.getClass().getSimpleName();
                logger.debug("Message received to sent to core is [{}], nothing to do", messageType);
            }
        }

        Map<String, Object> requestHeaders = sentMessage.getExtraHeaderDetails();
        String routingUrl = null;

        if (requestHeaders != null) {

            if (submitResponseRoutingUrlName != null) {
                routingUrl = (String) requestHeaders.get(submitResponseRoutingUrlName);
                if (logger.isDebugEnabled()) {
                    logger.debug("Submit Response routing header param URL[" + submitResponseRoutingUrlName + "] [" + routingUrl + "]");
                }
            }
        }

        if (routingUrl == null) {
            if (useDefaultRespRouting) {
                logger.warn("Couldn't find the response headers. Message routed to default location["
                        + smsMtResDefaultUrl + "]");
                routingUrl = smsMtResDefaultUrl + "/" + sentMessage.getNcsId();
            } else {
                if (logger.isWarnEnabled()) {
                    logger.warn("Response routing URL is not provided with header parameter["
                            + submitResponseRoutingUrlName
                            + "], and routing to default URL is also disabled. Response NOT sent to core.");
                    return;
                }
            }
        }

        logger.info("[" + sentMessage.getCorrelationId() + "]Message routed to [" + routingUrl + "]");

        if (logger.isDebugEnabled()) {
            logger.debug("[SENDIND-MSG-2-CORE-EXTRA]" + sentMessage);
        }
        sdpMessageSender.send(sentMessage, routingUrl);

        if (logger.isDebugEnabled()) {
            logger.debug("Sending SubmitSmResp to Core.........END");
        }
    }
}

