private void handleSubmitMessage(SmppMessage smppMessage) {
    if (smppMessage instanceof SubmitSm submitSm) {
        submitMessage(submitSm);
    } else if (smppMessage instanceof LargeSM largeSm) {
        submitMessage(largeSm);
    } else if (smppMessage instanceof SubmitMultiSm submitMultiSm) {
        submitMessage(submitMultiSm);
    } else if (smppMessage instanceof SubmitMultiLargeSm submitMultiLargeSm) {
        submitMessage(submitMultiLargeSm);
    } else if (smppMessage instanceof ReplaceSm replaceSm) {
        submitMessage(replaceSm);
    } else if (smppMessage instanceof ReplaceLargeSM replaceLargeSM) {
        submitMessage(replaceLargeSM);
    } else {
        throw new IllegalStateException("Unexpected object type[" + smppMessage.getClass() + "].");
    }
}

private void submitMessage(SubmitSm submitSmMessage) {
    NDC.push("CorrelationId[" + submitSmMessage.getCorrelationId() + "]");
    MDC.put("correlation-id", String.valueOf(submitSmMessage.getCorrelationId()));
    try {
        if (logger.isDebugEnabled()) {
            logger.debug("Start Submitting SubmitSm --------START");
        }
        boolean status = submitSmMessageHandler.sendMessage(submitSmMessage);
        if (status) {
            if (logger.isDebugEnabled()) {
                logger.debug("Finished sending SubmitSM to SMSC - Submit Successful");
            }
        } else {
            if (logger.isDebugEnabled()) {
                logger.debug("Finished sending SubmitSM to SMSC - Submit Fail");
            }
            submitSmMessageHandler.sendFailedResp2Core(submitSmMessage);
            TpsLogger.getInstance().incrementSmsFailed();
        }
        if (logger.isDebugEnabled()) {
            logger.debug("Finished Submitting SubmitSm --------END");
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    } finally {
        NDC.pop();
    }
}

