public void init() {
    BlockingQueue<Runnable> workQueue = new LinkedBlockingQueue<>();
    this.worker = new MonitoredExecutorService(
            poolSize,
            poolSize,
            0L,
            TimeUnit.MILLISECONDS,
            workQueue,
            new DaemonThreadFactory("Sms-Mt-Worker"),
            queueSizeLoggingInterval
    );
}


public void process(Processable processable) {
    SmsMtProcessMessage message = (SmsMtProcessMessage) processable;

    worker.submit(() -> {
        try {
            handleSubmitMessage(message.getMessage());
        } catch (Throwable e) {
            logger.error("Error while handling MT request", e);
        } finally {
            MDC.clear();
        }

