76	    /**
77	     * Paginated search by sp (company) name. Paginates over the matching
78	     * provisioned-app rows directly (one bulk DTO query, LIMIT/OFFSET on the
79	     * app rows themselves) so "size" means rows shown per page, not sps
80	     * matched - a page always holds exactly {@code size} apps (except the
81	     * last). Consecutive rows belonging to the same sp are grouped together
82	     * for display.
83	     *
84	     * @param spName search term (partial match against company name)
85	     * @param page   zero-based page number (over matching app rows)
86	     * @param size   page size
87	     * @return apps grouped by sp for the requested page, or {@code null} when no results
88	     */
89	    public List<AppSearchCriteriaBySp> findApplication(String spName, OidcUser user, int page, int size) throws Throwable {
90	        log.info("Search application for sp name[" + spName + "] by user " + user.getPreferredUsername() + " page [" + page + "] size [" + size + "]");
91	        try {
92	            List<ProvisionedAppSearchDTO> dtos = appRepository.findProvisionedAppDTOsBySpNameSearch(spName, page * size, size);
93	            if (dtos == null || dtos.isEmpty()) return null;
94	
95	            LinkedHashMap<Long, List<AppInfo>> appInfoBySpId = new LinkedHashMap<Long, List<AppInfo>>();
96	            List<AppInfo> allAppInfo = new ArrayList<AppInfo>();
97	            for (ProvisionedAppSearchDTO dto : dtos) {
98	                AppInfo appInfo = convertProvisionedAppDTOToAppInfo(dto);
99	                if (appInfo == null) continue;
100	                boolean useProd = dto.getProdAppId() != null && !"RETIRED".equals(dto.getProdCurrentState());
101	                Long spId = useProd ? dto.getProdSpId() : dto.getTestbedSpId();
102	                if (spId == null) continue;
103	                List<AppInfo> forSp = appInfoBySpId.get(spId);
104	                if (forSp == null) {
105	                    forSp = new ArrayList<AppInfo>();
106	                    appInfoBySpId.put(spId, forSp);
107	                }
108	                forSp.add(appInfo);
109	                allAppInfo.add(appInfo);
110	            }
111	            if (appInfoBySpId.isEmpty()) return null;
112	
113	            fetchRoutingKeysForApps(allAppInfo);
114	
115	            Map<Long, SpImpl> spById = new HashMap<Long, SpImpl>();
116	            for (SpImpl sp : spRepository.findSpsByIds(new ArrayList<Long>(appInfoBySpId.keySet()))) {
117	                spById.put(sp.getId(), sp);
118	            }
119	
120	            List<AppSearchCriteriaBySp> appSearchCriteriaList = new ArrayList<AppSearchCriteriaBySp>();
121	            for (Map.Entry<Long, List<AppInfo>> entry : appInfoBySpId.entrySet()) {
122	                SpImpl sp = spById.get(entry.getKey());
123	                if (sp != null) {
124	                    appSearchCriteriaList.add(new AppSearchCriteriaBySp(entry.getValue(), sp));
125	                }
126	            }
127	            if (appSearchCriteriaList.size() == 0) return null;
128	            return appSearchCriteriaList;
129	        } catch (Throwable e) {
130	            if (log.isErrorEnabled()) {
131	                log.error("Error occured while searching application " , e);
132	            }
133	            throw e;
134	        }
135	    }
