144	    public void downLoadToCsv(String spName, HttpServletResponse response) throws IllegalAccessException {
145	        try {
146	            List<SpImpl> splist = findBySpName(spName);
147	            List<String> recordList = null;
148	            log.info("application going to download for sp :" + spName + " sp list size" + splist.size());
149	            if(splist != null){
150	                log.info("Online csv downloading started...");
151	                recordList = csvDownLoadMangerService.downloadApplicationForSp(splist);
152	                log.info("Online csv downloading finished...");
153	            }
154	            setResponse(response, recordList);
155	        } catch (SpException e) {
156	            log.error("unable to find sp " + spName );
157	        } catch (IOException e) {
158	            log.error("unable to download for sp :" + spName );
159	        }
160	
161	    }
