163	    private List<String> getRecordListBySavedCsv() throws IOException {
164	        String file = getLatestCsvFile();
165	        if (log.isDebugEnabled()) {
166	            log.debug("Loading scheduler downloaded file [" + schedulerDownloadedLocation + "/" + file + "]");
167	        }
168	
169	        List<String> recordList = new ArrayList<>();
170	        try (BufferedReader reader = new BufferedReader(new FileReader(schedulerDownloadedLocation + "/" + file))) {
171	            String line;
172	            while ((line = reader.readLine()) != null) {
173	                recordList.add(line);
174	            }
175	        }
176	
177	        return recordList;
178	    }
179	
180	    private String getLatestCsvFile() throws IOException {
181	        //TODO: have to improve the file filtering logic
182	
183	        File csvDir = new File(schedulerDownloadedLocation);
184	        FilenameFilter filter = new FileListFilter(schedulerDownloadedFileName, schedulerDownloadedFileExtension);
185	
186	        File[] files = csvDir.listFiles(filter);
187	        Arrays.sort(files);
188	
189	        File file = null;
190	        try {
191	            file = files[files.length - 1];
192	        } catch (ArrayIndexOutOfBoundsException e) {
193	            log.error("Scheduler downloaded csv files not found at " + schedulerDownloadedLocation);
194	            throw new IOException();
195	        }
196	
197	        return file.getName();
198	    }
