200	    public void setResponse(HttpServletResponse response, List<String> recordList){
201	        try
202	        {
203	            String filename= fileName + getTime() + fileExtension ;
204	            response.reset();
205	            response.setContentType("text/csv");
206	            response.setHeader("Content-disposition","attachment; filename=" +filename);
207	            for(String record : recordList) {
208	                response.getOutputStream().write(record.getBytes());
209	                response.getOutputStream().write(CRLF_BYTES);
210	            }
211	            response.getOutputStream().flush();
212	        }
213	        catch(Exception e){
214	            log.error("Unable to write csv file " + e);
215	        }
216	    }
