package hsenidmobile.sdp.provisioning.v2.service;

import hsenidmobile.sdp.corelogic.domain.SpException;
import hsenidmobile.sdp.corelogic.domain.sla.*;
import hsenidmobile.sdp.corelogic.domain.sla.impl.SpImpl;
import hsenidmobile.sdp.corelogic.dto.ProvisionedAppSearchDTO;
import hsenidmobile.sdp.provisioning.v2.domain.AppInfo;
import hsenidmobile.sdp.provisioning.v2.view.AppSearchCriteriaBySp;
import hsenidmobile.sdp.provisioningstartupservices.csv.service.CsvDownLoadMangerService;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.oauth2.core.oidc.user.OidcUser;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.*;
import java.text.SimpleDateFormat;
import java.util.*;


@Transactional
@Service
public class ApplicationListBySpUserService extends BaseProvisioningService {
    private static final byte[] CRLF_BYTES = { '\r', '\n' };
    private static final String[] SEARCH_ALL_SPNAMES_TOKEN = {"%"};
    private final Log log = LogFactory.getLog(this.getClass());

    private final CsvDownLoadMangerService csvDownLoadMangerService;
    private final String mkRole;
    private final String spRole;
    private final String fileName;
    private final String fileExtension;
    private final String schedulerDownloadedFileName;
    private final String schedulerDownloadedLocation;
    private final String schedulerDownloadedFileExtension;

    @Autowired
    public ApplicationListBySpUserService(
            CsvDownLoadMangerService csvDownLoadMangerService,
            @Value("${marketing.role}") String mkRole,
            @Value("${sp.role}") String spRole,
            @Value("${csv.file.name}") String fileName,
            @Value("${file.extension}") String fileExtension,
            @Value("${scheduler.downloaded.location}") String schedulerDownloadedLocation,
            @Value("${scheduler.downloaded.file.name}") String schedulerDownloadedFileName,
            @Value("${scheduler.downloaded.file.extension}") String schedulerDownloadedFileExtension) {
        this.csvDownLoadMangerService = csvDownLoadMangerService;
        this.mkRole = mkRole;
        this.spRole = spRole;
        this.fileName = fileName;
        this.fileExtension = fileExtension;
        this.schedulerDownloadedLocation = schedulerDownloadedLocation;
        this.schedulerDownloadedFileName = schedulerDownloadedFileName;
        this.schedulerDownloadedFileExtension = schedulerDownloadedFileExtension;
    }

    /**
     * Paginated search by sp (company) name. Paginates over the matching
     * provisioned-app rows directly (one bulk DTO query, LIMIT/OFFSET on the
     * app rows themselves) so "size" means rows shown per page, not sps
     * matched - a page always holds exactly {@code size} apps (except the
     * last). Consecutive rows belonging to the same sp are grouped together
     * for display.
     *
     * @param spName search term (partial match against company name)
     * @param page   zero-based page number (over matching app rows)
     * @param size   page size
     * @return apps grouped by sp for the requested page, or {@code null} when no results
     */
    public List<AppSearchCriteriaBySp> findApplication(String spName, OidcUser user, int page, int size) throws Throwable {
        log.info("Search application for sp name[" + spName + "] by user " + user.getPreferredUsername() + " page [" + page + "] size [" + size + "]");
        try {
            List<ProvisionedAppSearchDTO> dtos = appRepository.findProvisionedAppDTOsBySpNameSearch(spName, page * size, size);
            if (dtos == null || dtos.isEmpty()) return null;

            LinkedHashMap<Long, List<AppInfo>> appInfoBySpId = new LinkedHashMap<Long, List<AppInfo>>();
            List<AppInfo> allAppInfo = new ArrayList<AppInfo>();
            for (ProvisionedAppSearchDTO dto : dtos) {
                AppInfo appInfo = convertProvisionedAppDTOToAppInfo(dto);
                if (appInfo == null) continue;
                boolean useProd = dto.getProdAppId() != null && !"RETIRED".equals(dto.getProdCurrentState());
                Long spId = useProd ? dto.getProdSpId() : dto.getTestbedSpId();
                if (spId == null) continue;
                List<AppInfo> forSp = appInfoBySpId.get(spId);
                if (forSp == null) {
                    forSp = new ArrayList<AppInfo>();
                    appInfoBySpId.put(spId, forSp);
                }
                forSp.add(appInfo);
                allAppInfo.add(appInfo);
            }
            if (appInfoBySpId.isEmpty()) return null;

            fetchRoutingKeysForApps(allAppInfo);

            Map<Long, SpImpl> spById = new HashMap<Long, SpImpl>();
            for (SpImpl sp : spRepository.findSpsByIds(new ArrayList<Long>(appInfoBySpId.keySet()))) {
                spById.put(sp.getId(), sp);
            }

            List<AppSearchCriteriaBySp> appSearchCriteriaList = new ArrayList<AppSearchCriteriaBySp>();
            for (Map.Entry<Long, List<AppInfo>> entry : appInfoBySpId.entrySet()) {
                SpImpl sp = spById.get(entry.getKey());
                if (sp != null) {
                    appSearchCriteriaList.add(new AppSearchCriteriaBySp(entry.getValue(), sp));
                }
            }
            if (appSearchCriteriaList.size() == 0) return null;
            return appSearchCriteriaList;
        } catch (Throwable e) {
            if (log.isErrorEnabled()) {
                log.error("Error occured while searching application " , e);
            }
            throw e;
        }
    }

    /**
     * Exact count of provisioned apps matching the search criteria, for pagination.
     */
    public long countApplications(String spName) throws SpException {
        return appRepository.countProvisionedAppsBySpNameSearch(spName);
    }

    public void downLoadToCsv(String spName, HttpServletResponse response) throws IllegalAccessException {
        try {
            List<SpImpl> splist = findBySpName(spName);
            List<String> recordList = null;
            log.info("application going to download for sp :" + spName + " sp list size" + splist.size());
            if(splist != null){
                log.info("Online csv downloading started...");
                recordList = csvDownLoadMangerService.downloadApplicationForSp(splist);
                log.info("Online csv downloading finished...");
            }
            setResponse(response, recordList);
        } catch (SpException e) {
            log.error("unable to find sp " + spName );
        } catch (IOException e) {
            log.error("unable to download for sp :" + spName );
        }

    }

    private List<String> getRecordListBySavedCsv() throws IOException {
        String file = getLatestCsvFile();
        if (log.isDebugEnabled()) {
            log.debug("Loading scheduler downloaded file [" + schedulerDownloadedLocation + "/" + file + "]");
        }

        List<String> recordList = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(schedulerDownloadedLocation + "/" + file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                recordList.add(line);
            }
        }

        return recordList;
    }

    private String getLatestCsvFile() throws IOException {
        //TODO: have to improve the file filtering logic

        File csvDir = new File(schedulerDownloadedLocation);
        FilenameFilter filter = new FileListFilter(schedulerDownloadedFileName, schedulerDownloadedFileExtension);

        File[] files = csvDir.listFiles(filter);
        Arrays.sort(files);

        File file = null;
        try {
            file = files[files.length - 1];
        } catch (ArrayIndexOutOfBoundsException e) {
            log.error("Scheduler downloaded csv files not found at " + schedulerDownloadedLocation);
            throw new IOException();
        }

        return file.getName();
    }

    public void setResponse(HttpServletResponse response, List<String> recordList){
        try
        {
            String filename= fileName + getTime() + fileExtension ;
            response.reset();
            response.setContentType("text/csv");
            response.setHeader("Content-disposition","attachment; filename=" +filename);
            for(String record : recordList) {
                response.getOutputStream().write(record.getBytes());
                response.getOutputStream().write(CRLF_BYTES);
            }
            response.getOutputStream().flush();
        }
        catch(Exception e){
            log.error("Unable to write csv file " + e);
        }
    }

    public String getTime(){
        Calendar today = Calendar.getInstance();
        SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd");
        SimpleDateFormat timeFormatter = new SimpleDateFormat("HH.mm.ss");
        return dateFormatter.format(today.getTime()) +":" + timeFormatter.format(today.getTime());
    }

    public List<SpImpl> findBySpName(String spName) throws SpException {
        List<SpImpl> splist = spRepository.findSpByName(spName);
        if(splist == null || splist.size() == 0) return null;
        return splist;
    }

    private class FileListFilter implements FilenameFilter {
        private String fileName;
        private String extension;

        public FileListFilter(String schedulerDownloadedFileName, String schedulerDownloadedFileExtension) {
            this.fileName = schedulerDownloadedFileName;
            this.extension = schedulerDownloadedFileExtension;
        }

        public boolean accept(File dir, String name) {
            boolean fileOK = true;

            if (this.fileName != null) {
                fileOK &= name.startsWith(this.fileName);
            }

            if (this.extension != null) {
                fileOK &= name.endsWith('.' + this.extension);
            }
            return fileOK;
        }
    }
}

