package hsenidmobile.sdp.provisioning.v2.controller.sp;

import hsenidmobile.sdp.corelogic.domain.SpException;
import hsenidmobile.sdp.corelogic.domain.sla.Sp;
import hsenidmobile.sdp.corelogic.domain.sla.impl.SpImpl;
import hsenidmobile.sdp.provisioning.v2.domain.AppDeatils;
import hsenidmobile.sdp.provisioning.v2.service.ApplicationDetailRequestService;
import hsenidmobile.sdp.provisioning.v2.service.ApplicationListBySpUserService;
import hsenidmobile.sdp.provisioning.v2.service.SpRegistrationService;
import hsenidmobile.sdp.provisioning.v2.view.AppSearchCriteriaBySp;
import hsenidmobile.sdp.provisioning.v2.view.ApplicationSearchCriteria;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.core.oidc.user.OidcUser;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.bind.support.SessionStatus;

import java.util.List;

@Controller
@RequestMapping("/listAppBySpUser")
@SessionAttributes({
        "listApplicationRequest",
        "applicationSearchCriteria",
        "serviceProviderImpl"
})
public class ListAppBySpUserController {

    private final static Logger logger = LoggerFactory.getLogger(ListAppBySpUserController.class);

    private final ApplicationListBySpUserService applicationListBySpUserService;
    private final ApplicationDetailRequestService applicationDetailRequestService;
    private final SpRegistrationService spRegistrationService;

    public ListAppBySpUserController(ApplicationListBySpUserService applicationListBySpUserService, 
                                    ApplicationDetailRequestService applicationDetailRequestService,
                                    SpRegistrationService spRegistrationService) {
        this.applicationListBySpUserService = applicationListBySpUserService;
        this.applicationDetailRequestService = applicationDetailRequestService;
        this.spRegistrationService = spRegistrationService;
    }

    @GetMapping
    public String listApplications(@AuthenticationPrincipal OidcUser user,
                                   @RequestParam(name = "applicationName", required = false) String applicationName,
                                   @RequestParam(value = "page", required = false, defaultValue = "0") int page,
                                   @RequestParam(value = "size", required = false, defaultValue = "10") int size,
                                   Model model) throws Throwable {
        logger.info("Displaying list applications page for user: [{}], page [{}], size [{}]", user.getPreferredUsername(), page, size);
        ApplicationSearchCriteria applicationSearchCriteria = new ApplicationSearchCriteria();
        applicationSearchCriteria.setApplicationName(applicationName);
        applicationSearchCriteria.setPage(page);
        applicationSearchCriteria.setSize(size);
        model.addAttribute("applicationSearchCriteria", applicationSearchCriteria);
        try {
            if (applicationSearchCriteria.getApplicationName() != null
                    && !applicationSearchCriteria.getApplicationName().trim().isEmpty()) {
                List<AppSearchCriteriaBySp> appSearchCriteriaBySps = applicationListBySpUserService.findApplication(
                        applicationSearchCriteria.getApplicationName(), user, page, size);
                if (appSearchCriteriaBySps == null || appSearchCriteriaBySps.isEmpty()) {
                    logger.error("No Application Found for app name : [{}]", applicationSearchCriteria.getApplicationName());
                    model.addAttribute("noAppFoundEx", "no_app_found");
                }
                long totalCount = applicationListBySpUserService.countApplications(applicationSearchCriteria.getApplicationName());
                applicationSearchCriteria.setTotalElements(totalCount);
                model.addAttribute("listApplicationRequest", appSearchCriteriaBySps);
            }
        } catch (Throwable ex) {
            model.addAttribute("listApplicationRequest",  null);
            logger.error("Error while listing applications for user [{}]: {}", user.getPreferredUsername(), ex.getMessage(), ex);
            model.addAttribute("noAppFoundEx", "no_app_found");
        }

        return "serviceProvider/listApplicationBySpUser";
    }

    @GetMapping("/viewApp")
    public String viewAppProfileDetails(@RequestParam("appId") String appId, Model model) {
        logger.info("Viewing application details for appId: {}", appId);
        try {
            AppDeatils appDeatils = applicationDetailRequestService.getApplicationDetails(appId);
            logger.info("App details for appId: {}", appDeatils);
            model.addAttribute("applicationDetails", appDeatils);
            model.addAttribute("appName", appDeatils.getAppName());
            model.addAttribute("hostLocation", appDeatils.getHostLocation());
            return "serviceProvider/viewAppDetailsSearchBySp";
        } catch (Exception e) {
            logger.error("Error retrieving application details for appId: {}", appId, e);
            return "redirect:/listAppBySpUser";
        }
    }

    @GetMapping("/viewSp")
    public String viewServiceProviderDetail(@RequestParam("spId") String spId, Model model) {
        logger.info("Viewing service provider details for spId: {}", spId);
        try {
            SpImpl serviceProviderImpl = (SpImpl) spRegistrationService.getSpById(spId);
            if (serviceProviderImpl == null) {
                logger.error("No service provider found with ID: {}", spId);
                model.addAttribute("spSearchError", "no_sp_found");
                return "redirect:/listAppBySpUser";
            }

            logger.info("Service provider details retrieved: {}", serviceProviderImpl);
            model.addAttribute("serviceProviderImpl", serviceProviderImpl);
            return "serviceProvider/viewSpForSpSearch";
        } catch (SpException e) {
            logger.error("Error retrieving service provider details for spId: {}", spId, e);
            return "redirect:/listAppBySpUser";
        }
    }

    @GetMapping("/downloadCsv")
    public void downloadCsv(@RequestParam(name = "applicationName") String applicationName, HttpServletResponse response) {
        logger.info("Starting CSV download for application name: [{}]", applicationName);
        try {
            // Validate application name parameter
            if (applicationName == null || applicationName.trim().isEmpty()) {
                logger.error("Application name is null or empty");
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                return;
            }

            // Trim and validate the application name
            String trimmedApplicationName = applicationName.trim();
            if (trimmedApplicationName.isEmpty()) {
                logger.error("Application name is empty after trimming");
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                return;
            }

            applicationListBySpUserService.downLoadToCsv(trimmedApplicationName, response);
            logger.info("Completed CSV download for application name: [{}]", trimmedApplicationName);
        } catch (Exception e) {
            logger.error("Error during CSV download for application name [{}]: {}", applicationName, e.getMessage(), e);
            try {
                response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
                response.getWriter().write("Error occurred while downloading CSV");
            } catch (Exception ex) {
                logger.error("Error writing error response: {}", ex.getMessage(), ex);
            }
        }
    }

    @RequestMapping("/clearSession")
    public String clearSession(SessionStatus sessionStatus) {
        sessionStatus.setComplete();
        return "redirect:/listAppBySpUser";
    }



}

