@PostMapping("/smsSla")
public String submitSmsSla(@ModelAttribute("ncsSlaImpl") ProvisioningNcsSla ncsSlaImpl,
                           BindingResult error,
                           @ModelAttribute("crAppInfo") CrDraftAppInfo crAppInfo,
                           @ModelAttribute("appId") String appId,
                           @ModelAttribute("moOldChargingSlaType") String moOldChargingSlaType,
                           @ModelAttribute("mtOldChargingSlaType") String mtOldChargingSlaType,
                           @RequestParam(value = "action") CrAppAction action,
                           Model model) {
    try {
        crDraftRequestService.handleChargingSlaChange(ncsSlaImpl, moOldChargingSlaType, mtOldChargingSlaType);

        appReqValidator.validateNewApplicationSmsSla(ncsSlaImpl, error);
        crDraftRequestService.validateBilledPartyForSms(crAppInfo, ncsSlaImpl, error);
        if (error.hasErrors()) {
            setupSmsSla(ncsSlaImpl,crAppInfo, model);
            return "cr/stateflow/crDraft/sla/sms";
        }

        crAppInfo = crDraftRequestService.updateAppNcsSla(crAppInfo, ncsSlaImpl);

        model.addAttribute("crAppInfo", crAppInfo);

        logger.info("App : [{}] SMS SLA configured successfully", appId);

