+    /**
+     * Convert ProvisionedAppSearchDTO to AppInfo (DTO-based, no entity loading)
+     * This avoids the N+1 query problem by not loading full entity graphs
+     */
+    protected AppInfo convertProvisionedAppDTOToAppInfo(ProvisionedAppSearchDTO dto) {
+        try {
+            // Determine active app (prod if exists and not retired, else testbed)
+            String appName = null;
+            String appIdString = null;
+            String spCompanyName = null;
+            String currentState = null;
+            Timestamp limitedProdTime = null;
+
+            if (dto.getProdAppId() != null && !"RETIRED".equals(dto.getProdCurrentState())) {
+                // Use production app
+                appName = dto.getProdAppName();
+                appIdString = dto.getProdAppIdString();
+                spCompanyName = dto.getProdSpCompanyName();
+                currentState = dto.getProdCurrentState();
+                limitedProdTime = dto.getProdLimitedProductionTime();
+            } else if (dto.getTestbedAppId() != null) {
+                // Use testbed app
+                appName = dto.getTestbedAppName();
+                appIdString = dto.getTestbedAppIdString();
+                spCompanyName = dto.getTestbedSpCompanyName();
+                currentState = dto.getTestbedCurrentState();
+                limitedProdTime = dto.getTestbedLimitedProductionTime();
+            }
+
+            if (appName == null || "RETIRED".equals(currentState)) {
+                return null;
+            }
+
+            // Routing keys will be fetched in bulk after getting all apps
+            String smsShortCode = "N/A";
+            String mmsShortCode = "N/A";
+
+            // Create AppInfo
+            AppInfo appInfo = new AppInfo(dto.getAppId(), appName, spCompanyName,
+                smsShortCode, mmsShortCode);
+            appInfo.setAppId(appIdString); // Use app_id string for routing key lookup
+            appInfo.setTestbedAppId(dto.getTestbedAppIdString());
+
+            // Set active flag
+            if ("ACTIVE".equals(currentState) && dto.getCrAppReqId() == null) {
+                appInfo.setActive(true);
+            }
+
+            // Set limited production time
+            if (limitedProdTime != null) {
+                appInfo.setLimittedProductionTime(dateToString(new Date(limitedProdTime.getTime())));
+            }
+
+            // Set state from flags
+            setStateNameFromDTO(dto, appInfo);
+
+            // Set approval detail manager if state is set
+            if (appInfo.getState() != null) {
+                // Note: createNormalFlowApprovalDetailManager requires ProvisionedApp entity
+                // For now, we skip this as it has not being used
+            }else if(appInfo.getState() == null && dto.getProdAppId() != null){
+                String crPreviousState = dto.getCrProvFlowState();
+
+                if ("LIMITED_PRODUCTION".equals(crPreviousState)) {
+
+                    appInfo.setState(ProvisioningStates.AppState.LIMITED_PRODUCTION);
+
+                }else if ("ACTIVE_PRODUCTION".equals(crPreviousState)){
+
+                    appInfo.setState(ProvisioningStates.AppState.ACTIVE_PRODUCTION);
+
+                    if ("ACTIVE".equals(dto.getProdCurrentState())) {
+                        appInfo.setActive(true);
+                    }
+                }else {
+                    appInfo.setState(ProvisioningStates.AppState.ACTIVE_PRODUCTION);
+
+                    if ("ACTIVE".equals(dto.getProdCurrentState())) {
+                        appInfo.setActive(true);
+                    }
+                }
+            }
+
+            return appInfo;
+
+        } catch (Exception e) {
+            log.error("Error converting ProvisionedAppSearchDTO to AppInfo", e);
+            return null;
+        }
+    }
+
+    /**
+     * Bulk fetch routing keys for all apps to avoid N+1 problem
+     * Only fetches routing keys for NCS types that are actually configured.
+     * Handles both provisioned apps (using app.app_id) and requested apps (using app_name)
+     */
+    protected void fetchRoutingKeysForApps(List<AppInfo> appInfoList) {
+        if (appInfoList == null || appInfoList.isEmpty()) {
+            return;
+        }
+
+        try {
+            // Step 1: Separate provisioned apps from requested apps
+            List<String> provisionedAppIds = new ArrayList<>();
+            List<String> requestedAppNames = new ArrayList<>();
+            Map<String, AppInfo> provAppIdToInfo = new HashMap<>();
+            Map<String, AppInfo> reqAppNameToInfo = new HashMap<>();
+
+            for (AppInfo appInfo : appInfoList) {
+                String appId = appInfo.getAppId();
+                if (appId != null && !appId.isEmpty()) {
+                    // Check if this is a requested app or provisioned app
+                    if (appInfo.getState() == ProvisioningStates.AppState.REQUESTED_APPLICATION ||
+                        appInfo.getState() == ProvisioningStates.AppState.APPROVED_APPLICATION_REQUEST) {
+                        // This is a requested app - uses app_name as ID
+                        requestedAppNames.add(appInfo.getApplicationName());
+                        reqAppNameToInfo.put(appInfo.getApplicationName(), appInfo);
+                    } else {
+                        appId = appInfo.getState() == ProvisioningStates.AppState.PRE_ACTIVE_PRODUCTION ?
+                                appInfo.getTestbedAppId() : appId;
+                        // This is a provisioned app - uses app.app_id
+                        provisionedAppIds.add(appId);
+                        provAppIdToInfo.put(appId, appInfo);
+                    }
+                }
+            }
+
+            if (provisionedAppIds.isEmpty() && requestedAppNames.isEmpty()) {
+                return;
+            }
+
+            // Step 2: Bulk fetch NCS SLAs for provisioned apps
+            Map<String, List<NcsSlaLookupDTO>> provisionedNcsSlas = new HashMap<>();
+            if (!provisionedAppIds.isEmpty()) {
+                provisionedNcsSlas = appRepository.findNcsSlasByAppIds(provisionedAppIds);
+            }
+
+            // Step 3: Bulk fetch NCS SLAs for requested apps
+            Map<String, List<NcsSlaLookupDTO>> requestedNcsSlas = new HashMap<>();
+            if (!requestedAppNames.isEmpty()) {
+                requestedNcsSlas = appRepository.findNcsSlasByAppReqNames(requestedAppNames);
+            }
+
+            // Step 4: Fetch routing keys for provisioned apps
+            for (Map.Entry<String, List<NcsSlaLookupDTO>> entry : provisionedNcsSlas.entrySet()) {
+                String appId = entry.getKey();
+                List<NcsSlaLookupDTO> ncsSlas = entry.getValue();
+                AppInfo appInfo = provAppIdToInfo.get(appId);
+
+                if (appInfo == null) {
+                    continue;
+                }
+
+                for (NcsSlaLookupDTO ncsSla : ncsSlas) {
+                    try {
+                        String ncsIdString = ncsSla.getNcsIdString();
+                        String ncsType = ncsSla.getNcsType();
+                        List<RoutingKey> routingKeys = routingKeyRepository.findRoutingKeysForApp(
+                            ncsIdString, appId);
+
+                        if (routingKeys != null && !routingKeys.isEmpty()) {
+                            String shortCode = routingKeys.get(0).getShortcode();
+
+                            // Set appropriate shortcode based on NCS type
+                            if ("SMS".equals(ncsType)) {
+                                appInfo.setSmsShortCode(shortCode);
+                            } else if ("MMS".equals(ncsType)) {
+                                appInfo.setMmsShortCode(shortCode);
+                            }
+                        }
+                    } catch (Exception e) {
+                        log.warn("Error fetching routing key for provisioned app [" + appId + "], NCS [" + ncsSla.getNcsIdString() + "]: " + e.getMessage());
+                    }
+                }
+            }
+
+            // Step 5: Fetch routing keys for requested apps
+            for (Map.Entry<String, List<NcsSlaLookupDTO>> entry : requestedNcsSlas.entrySet()) {
+                String appName = entry.getKey();
+                List<NcsSlaLookupDTO> ncsSlas = entry.getValue();
+                AppInfo appInfo = reqAppNameToInfo.get(appName);
+
+                if (appInfo == null) {
+                    continue;
+                }
+
+                for (NcsSlaLookupDTO ncsSla : ncsSlas) {
+                    try {
+                        String ncsIdString = ncsSla.getNcsIdString();
+                        String ncsType = ncsSla.getNcsType();
+                        List<RoutingKey> routingKeys = routingKeyRepository.findRoutingKeysForApp(
+                            ncsIdString, appName);
+
+                        if (routingKeys != null && !routingKeys.isEmpty()) {
+                            String shortCode = routingKeys.get(0).getShortcode();
+
+                            // Set appropriate shortcode based on NCS type
+                            if ("SMS".equals(ncsType)) {
