+package hsenidmobile.sdp.reportviewer.v2.config;
+
+import org.springframework.context.event.ContextClosedEvent;
+import org.springframework.context.event.EventListener;
+import org.springframework.stereotype.Component;
+
+/**
+ * Tracks whether the application has begun shutting down.
+ * <p>
+ * {@link ContextClosedEvent} is published at the very start of the Spring context shutdown,
+ * before any bean is destroyed - so before the c3p0 datasource closes and tears down its pooled
+ * connections. Components that would otherwise mistake that routine teardown for a database
+ * failure (see {@link ConnectionListener} and {@link DbConnectionHealthScheduler}) consult this
+ * flag to stay quiet during the stop.
+ */
+@Component
+public class ApplicationShutdownState {
+
+    private volatile boolean shuttingDown = false;
+
+    @EventListener(ContextClosedEvent.class)
+    public void onContextClosed() {
+        shuttingDown = true;
+    }
+
+    public boolean isShuttingDown() {
+        return shuttingDown;
+    }
+}
