+package hsenidmobile.sdp.reportviewer.v2.controller;
+
+import jakarta.servlet.http.HttpServletRequest;
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+import org.springframework.http.HttpStatus;
+import org.springframework.http.MediaType;
+import org.springframework.http.ResponseEntity;
+import org.springframework.web.ErrorResponse;
+import org.springframework.web.bind.annotation.ControllerAdvice;
+import org.springframework.web.bind.annotation.ExceptionHandler;
+import org.springframework.web.servlet.ModelAndView;
+
+import java.nio.charset.Charset;
+import java.util.List;
+
+/**
+ * Single place where an unhandled exception - typically a database failure surfacing as a
+ * DataAccessException or a SQLException wrapped by JasperReports - is turned into something
+ * the user can actually see.
+ * <p>
+ * Previously the report controllers returned an empty 500 body. Spring MVC commits that with
+ * setStatus() rather than sendError(), so the container never dispatched to /error and the
+ * browser simply showed a blank tab. Rendering the error view here keeps the response
+ * meaningful, and the XML endpoints get a parseable body instead of whatever the container
+ * would have produced.
+ */
+@ControllerAdvice
+public class GlobalExceptionHandler {
+
+    private static final Logger logger = LoggerFactory.getLogger(GlobalExceptionHandler.class);
+
+    private static final String ERROR_VIEW = "error";
+
+    /**
+     * Endpoints consumed by the in-page XMLHttpRequest helpers. They must not receive the
+     * Thymeleaf error page, which their responseXML parsing would choke on.
+     */
+    private static final List<String> XML_ENDPOINTS = List.of(
+            "/loadApplications",
+            "/loadServiceTypes",
+            "/testSummaryDataStatus"
+    );
+
+    private static final MediaType XML_ISO_8859_1 =
+            new MediaType(MediaType.TEXT_XML, Charset.forName("ISO-8859-1"));
+
+    private final ReportErrorMessages errorMessages;
+
+    public GlobalExceptionHandler(ReportErrorMessages errorMessages) {
+        this.errorMessages = errorMessages;
+    }
+
+    @ExceptionHandler(Exception.class)
+    public Object handleUncaughtException(Exception e, HttpServletRequest request) throws Exception {
+        // Spring already models its own MVC exceptions (bad request, method not allowed,
+        // unsupported media type, ...) as proper 4xx responses. Rethrow so they keep their
+        // status instead of being masked as a 500.
+        if (e instanceof ErrorResponse) {
+            throw e;
+        }
+
+        logger.error("Unhandled exception for [{} {}]", request.getMethod(), request.getRequestURI(), e);
+
+        if (isXmlEndpoint(request)) {
+            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
+                    .contentType(XML_ISO_8859_1)
+                    .body("<?xml version=\"1.0\"?><sdp-error><status>error</status></sdp-error>");
+        }
+
+        ModelAndView modelAndView = new ModelAndView(ERROR_VIEW, HttpStatus.INTERNAL_SERVER_ERROR);
+        modelAndView.addObject("errorCode", HttpStatus.INTERNAL_SERVER_ERROR.value());
+        modelAndView.addObject("errorMessage", errorMessages.unavailable());
+        return modelAndView;
+    }
+
+    private boolean isXmlEndpoint(HttpServletRequest request) {
+        String servletPath = request.getServletPath();
+        String requestUri = request.getRequestURI();
+        return XML_ENDPOINTS.stream().anyMatch(endpoint ->
+                (servletPath != null && servletPath.startsWith(endpoint))
+                        || (requestUri != null && requestUri.contains(endpoint)));
+    }
+}
