+package hsenidmobile.sdp.reportviewer.v2.controller;
+
+import org.springframework.context.MessageSource;
+import org.springframework.context.i18n.LocaleContextHolder;
+import org.springframework.stereotype.Component;
+
+/**
+ * The user-facing text for a failed report request, in one place.
+ * <p>
+ * Two paths reach the same error page and must say the same thing: {@link GlobalExceptionHandler}
+ * when a report POST blows up, and {@link CustomErrorController#reportUnavailable} when an in-page
+ * XHR fails and the browser navigates here.
+ */
+@Component
+public class ReportErrorMessages {
+
+    private static final String UNAVAILABLE_KEY = "report.service.unavailable";
+    private static final String UNAVAILABLE_FALLBACK =
+            "Report service is temporarily unavailable. Please try again later.";
+
+    private final MessageSource messageSource;
+
+    public ReportErrorMessages(MessageSource messageSource) {
+        this.messageSource = messageSource;
+    }
+
+    /**
+     * Deliberately generic - the cause (database down, query failure, ...) belongs in the log,
+     * not on a screen the customer can see.
+     */
+    public String unavailable() {
+        return messageSource.getMessage(
+                UNAVAILABLE_KEY,
+                null,
+                UNAVAILABLE_FALLBACK,
+                LocaleContextHolder.getLocale()
+        );
+    }
+}

