diff --git a/modules/reporting/report-viewer-v2/src/main/resources/templates/fragments/loading.html b/modules/reporting/report-viewer-v2/src/main/resources/templates/fragments/loading.html
new file mode 100644
index 000000000..2ade708a5
--- /dev/null
+++ b/modules/reporting/report-viewer-v2/src/main/resources/templates/fragments/loading.html
@@ -0,0 +1,132 @@
+<!DOCTYPE html>
+<html lang="en" xmlns:th="http://www.thymeleaf.org">
+
+<!--
+    Busy indicator for the report pages.
+
+    The report forms talk to /testSummaryDataStatus, /loadApplications and /loadServiceTypes
+    over XMLHttpRequest. Those calls go through the same c3p0 pool as the reports themselves,
+    so when the database is unreachable they sit for the full checkoutTimeout (5s) before
+    failing - during which the page looked completely idle.
+
+    Included once from fragments/footer.html, which every report page already replaces in.
+-->
+<th:block th:fragment="reportBusy">
+
+    <style>
+        .report-spinner {
+            display: inline-block;
+            width: 0.875rem;
+            height: 0.875rem;
+            margin-right: 0.5rem;
+            vertical-align: -0.125rem;
+            border: 2px solid currentColor;
+            border-right-color: transparent;
+            border-radius: 50%;
+            animation: report-spin 0.6s linear infinite;
+        }
+
+        @keyframes report-spin {
+            to {
+                transform: rotate(360deg);
+            }
+        }
+
+        .report-busy {
+            cursor: progress;
+        }
+    </style>
+
+    <script th:inline="javascript">
+        (function () {
+            var LOADING_TEXT = [[#{report.loading}]];
+
+            // only surface the indicator once a request is actually slow, so a healthy
+            // database (sub-100ms here) never makes the page flicker
+            var DELAY_MS = 300;
+
+            // last resort so a hung request can never leave a control stuck disabled
+            var MAX_BUSY_MS = 60000;
+
+            var showTimer = null;
+            var failsafeTimer = null;
+            var target = null;
+            var restore = null;
+
+            function busyButton(button) {
+                var group = button.parentNode
+                        ? button.parentNode.querySelectorAll('button')
+                        : [button];
+                var markup = button.innerHTML;
+                var i;
+
+                for (i = 0; i < group.length; i++) {
+                    group[i].disabled = true;
+                }
+                button.innerHTML = '<span class="report-spinner"></span>' + LOADING_TEXT;
+                button.className += ' report-busy';
+
+                return function () {
+                    button.innerHTML = markup;
+                    button.className = button.className.replace(' report-busy', '');
+                    for (i = 0; i < group.length; i++) {
+                        group[i].disabled = false;
+                    }
+                };
+            }
+
+            function busySelect(select) {
+                var options = select.innerHTML;
+
+                select.innerHTML = '<option>-- ' + LOADING_TEXT + ' --</option>';
+                select.disabled = true;
+                select.className += ' report-busy';
+
+                return function () {
+                    // put the previous options back; on success the parse callback runs
+                    // straight after this and repopulates, on failure the user keeps the
+                    // list they had
+                    select.innerHTML = options;
+                    select.disabled = false;
+                    select.className = select.className.replace(' report-busy', '');
+                };
+            }
+
+            function show() {
+                showTimer = null;
+                if (!target) {
+                    return;
+                }
+                restore = (target.tagName === 'SELECT') ? busySelect(target) : busyButton(target);
+            }
+
+            window.reportBusyStart = function (element) {
+                window.reportBusyStop();
+                if (!element) {
+                    return;
+                }
+                target = element;
+                showTimer = window.setTimeout(show, DELAY_MS);
+                failsafeTimer = window.setTimeout(window.reportBusyStop, MAX_BUSY_MS);
+            };
+
+            window.reportBusyStop = function () {
+                if (showTimer !== null) {
+                    window.clearTimeout(showTimer);
+                    showTimer = null;
+                }
+                if (failsafeTimer !== null) {
+                    window.clearTimeout(failsafeTimer);
+                    failsafeTimer = null;
+                }
+                if (restore) {
+                    restore();
+                    restore = null;
+                }
+                target = null;
+            };
+        })();
+    </script>
+
+</th:block>
+</html>

